bool FetchServiceStubDispatch::Accept(
    FetchService* impl,
    mojo::Message* message) {
  switch (static_cast<messages::FetchService>(message->header()->name)) {
    case messages::FetchService::kPostRequest: {
      break;
    }
    case messages::FetchService::kDownloadToStream: {
      break;
    }
  }
  return false;
}

// static
bool FetchServiceStubDispatch::AcceptWithResponder(
    FetchService* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::FetchService>(message->header()->name)) {
    case messages::FetchService::kPostRequest: {
      internal::FetchService_PostRequest_Params_Data* params =
          reinterpret_cast<
              internal::FetchService_PostRequest_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for FetchService.0
      bool success = true;
      ::GURL p_url{};
      std::string p_post_data{};
      std::string p_content_type{};
      std::vector<HttpHeaderPtr> p_additional_headers{};
      FetchService_PostRequest_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadUrl(&p_url))
        success = false;
      if (success && !input_data_view.ReadPostData(&p_post_data))
        success = false;
      if (success && !input_data_view.ReadContentType(&p_content_type))
        success = false;
      if (success && !input_data_view.ReadAdditionalHeaders(&p_additional_headers))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            FetchService::Name_, 0, false);
        return false;
      }
      auto callback =
          FetchService_PostRequest_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->PostRequest(        
        std::move(p_url), 
        std::move(p_post_data), 
        std::move(p_content_type), 
        std::move(p_additional_headers), std::move(callback));
      return true;
    }
    case messages::FetchService::kDownloadToStream: {
      internal::FetchService_DownloadToStream_Params_Data* params =
          reinterpret_cast<
              internal::FetchService_DownloadToStream_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for FetchService.1
      bool success = true;
      ::GURL p_url{};
      ::mojo::ScopedDataPipeProducerHandle p_response_stream{};
      FetchService_DownloadToStream_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadUrl(&p_url))
        success = false;
      if (success)
        p_response_stream = input_data_view.TakeResponseStream();
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            FetchService::Name_, 1, false);
        return false;
      }
      auto callback =
          FetchService_DownloadToStream_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->DownloadToStream(        
        std::move(p_url), 
        std::move(p_response_stream), std::move(callback));
      return true;
    }
  }
  return false;
}
