// static
bool StructTraits<::updater::mojom::HttpHeader::DataView, ::updater::mojom::HttpHeaderPtr>::Read(
    ::updater::mojom::HttpHeader::DataView input,
    ::updater::mojom::HttpHeaderPtr* output) {
  bool success = true;
  ::updater::mojom::HttpHeaderPtr result(::updater::mojom::HttpHeader::New());
  
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadValue(&result->value))
        success = false;
  *output = std::move(result);
  return success;
}

