void FetchServiceAsyncWaiter::PostRequest(
    const ::GURL& url, const std::string& post_data, const std::string& content_type, std::vector<HttpHeaderPtr> additional_headers, ::mojo::PendingReceiver<PostRequestObserver>* out_observer) {
  base::RunLoop loop;
  proxy_->PostRequest(
      std::move(url),
      std::move(post_data),
      std::move(content_type),
      std::move(additional_headers),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::PendingReceiver<PostRequestObserver>* out_observer
,
             ::mojo::PendingReceiver<PostRequestObserver> observer) {*out_observer = std::move(observer);
            loop->Quit();
          },
          &loop,
          out_observer));
  loop.Run();
}

::mojo::PendingReceiver<PostRequestObserver> FetchServiceAsyncWaiter::PostRequest(
    const ::GURL& url, const std::string& post_data, const std::string& content_type, std::vector<HttpHeaderPtr> additional_headers) {
  ::mojo::PendingReceiver<PostRequestObserver> async_wait_result;
  PostRequest(std::move(url),std::move(post_data),std::move(content_type),std::move(additional_headers),&async_wait_result);
  return async_wait_result;
}

void FetchServiceAsyncWaiter::DownloadToStream(
    const ::GURL& url, ::mojo::ScopedDataPipeProducerHandle response_stream, ::mojo::PendingReceiver<FileDownloadObserver>* out_observer) {
  base::RunLoop loop;
  proxy_->DownloadToStream(
      std::move(url),
      std::move(response_stream),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::PendingReceiver<FileDownloadObserver>* out_observer
,
             ::mojo::PendingReceiver<FileDownloadObserver> observer) {*out_observer = std::move(observer);
            loop->Quit();
          },
          &loop,
          out_observer));
  loop.Run();
}

::mojo::PendingReceiver<FileDownloadObserver> FetchServiceAsyncWaiter::DownloadToStream(
    const ::GURL& url, ::mojo::ScopedDataPipeProducerHandle response_stream) {
  ::mojo::PendingReceiver<FileDownloadObserver> async_wait_result;
  DownloadToStream(std::move(url),std::move(response_stream),&async_wait_result);
  return async_wait_result;
}






